<?php
require_once 'custom/HrDocumentSupport.php';require_once '/opt/hr/HrUi.php';global $current_user;
$_SESSION['hr_csrf']??=bin2hex(random_bytes(24));$error='';$title='';$source='leave';$config=null;
if($_SERVER['REQUEST_METHOD']==='POST')try{
 $title=is_string($_POST['title']??null)?$_POST['title']:'';$source=is_string($_POST['source']??null)?$_POST['source']:'';
 if(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['hr_csrf'],$_POST['csrf']))throw new RuntimeException('Сессия формы устарела. Обновите страницу.');
 $key=hrCloneTemplate($source,$title);header('Location: '.hrUiUrl('HrTemplates',['edit'=>$key,'created'=>1]),true,303);exit;
}catch(Throwable $e){$error=$e->getMessage();}
$edit=$_GET['edit']??'';
if($edit&&$current_user->isAdmin()&&isset(hrTemplates()[$edit])){
 hrInitTemplates();$file='template-'.$edit.'.docx';$config=['documentType'=>'word','height'=>'800px','width'=>'100%','document'=>['fileType'=>'docx','key'=>substr(hash_file('sha256',hrDir().'/'.$file),0,40),'title'=>hrTemplates()[$edit].'.docx','url'=>hrResourceUrl($file),'permissions'=>['edit'=>true]],'editorConfig'=>['customization'=>['forcesave'=>true],'lang'=>'ru','mode'=>'edit','callbackUrl'=>hrResourceUrl($file,'callback'),'user'=>['id'=>$current_user->id,'name'=>$current_user->user_name]]];$config['token']=hrJwt($config);
}
if($config){unset($config['token']);$config['editorConfig']['customization']['uiTheme']=($_COOKIE['hr_theme']??'light')==='dark'?'theme-dark':'theme-light';$config['token']=hrJwt($config);}
?><!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Шаблоны документов</title><?php hrUiStyle();?><body class="hr-page"><main class="hr-shell"><?php hrUiNav('templates');?><h1>Шаблоны документов</h1><p class="hr-muted">Общие формы для генерации документов сотрудников. <a href="<?=hrUiEscape(hrUiGuide('templates'))?>">Как создать и настроить шаблон</a></p>
<?php if($error):?><div class="error" role="alert"><?=hrUiEscape($error)?></div><?php endif?><?php if(isset($_GET['created'])):?><div class="success">Копия создана. Измените текст в редакторе и сохраните шаблон.</div><?php endif?>
<?php if($current_user->isAdmin()):?><form class="hr-panel" method="post" action="<?=hrUiEscape(hrUiUrl('HrTemplates'))?>"><h2>Создать шаблон на основе существующего</h2><input type="hidden" name="csrf" value="<?=hrUiEscape($_SESSION['hr_csrf'])?>"><div class="hr-form-grid"><label>Название нового шаблона <input name="title" value="<?=hrUiEscape($title)?>" placeholder="Например, рапорт на учебный отпуск" maxlength="120" required></label><label>Шаблон-основа <select name="source"><?php foreach(hrTemplates() as $key=>$label):?><option value="<?=hrUiEscape($key)?>" <?=$key===$source?'selected':''?>><?=hrUiEscape($label)?></option><?php endforeach?></select></label></div><p class="hr-hint">Копия сохраняет заполняемые блоки оригинала. Можно изменить текст и оформление, затем проверить результат на сотруднике.</p><button>Создать копию</button></form><?php else:?><p class="hr-panel">Шаблоны доступны для генерации. Создание и редактирование выполняет администратор.</p><?php endif?>
<div class="hr-table-wrap hr-panel"><table class="hr-table"><thead><tr><th>Название</th><th>Тип данных</th><th>Действие</th></tr></thead><tbody><?php foreach(hrTemplates() as $key=>$label):?><tr><td><?=hrUiEscape($label)?></td><td><?=hrUiEscape(['leave'=>'Параметры отпуска и карточка','awards'=>'Карточка и награды','service'=>'Карточка и периоды службы'][hrTemplateKind($key)]??'Карточка')?></td><td><?php if($current_user->isAdmin()):?><a href="<?=hrUiEscape(hrUiUrl('HrTemplates',['edit'=>$key]))?>">Редактировать в ONLYOFFICE</a><?php else:?>Доступен<?php endif?></td></tr><?php endforeach?></tbody></table></div>
<?php if($config):?><h2><?=hrUiEscape(hrTemplates()[$edit])?></h2><p class="hr-hint">Сохраняйте теги заполняемых блоков. После правок нажмите «Сохранить» и закройте редактор перед пробной генерацией.</p><div id="editor"></div><script src="<?=hrUiEscape(hrOfficePublicUrl())?>/web-apps/apps/api/documents/api.js"></script><script>var officeConfig=<?=json_encode($config,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP)?>;new DocsAPI.DocEditor('editor',officeConfig);</script><?php endif?>
</main></body></html>
